public class CaseSurveyJob implements Queueable {

    private final Id caseId;
    private final List<Id> remainingIds;

    /**
     * Simple constructor – process a single case with no chain.
     */
    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
        this.remainingIds = null;
    }

    /**
     * Chain constructor – process one case, then enqueue the next.
     * Used when the number of cases exceeds the 50-enqueue-per-transaction limit.
     */
    public CaseSurveyJob(Id caseId, List<Id> remainingIds) {
        this.caseId = caseId;
        this.remainingIds = remainingIds;
    }

    public void execute(QueueableContext context) {
        processCase();

        // Continue the chain if there are more cases to handle
        if (remainingIds != null && !remainingIds.isEmpty()) {
            Id nextId = remainingIds.get(0);
            List<Id> rest = new List<Id>(remainingIds);
            rest.remove(0);
            if (!rest.isEmpty()) {
                System.enqueueJob(new CaseSurveyJob(nextId, rest));
            } else {
                System.enqueueJob(new CaseSurveyJob(nextId));
            }
        }
    }

    private void processCase() {
        Case c = [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id = :caseId];

        // Defensive: the case may have been deleted or its contact cleared
        // between enqueue and execution
        if (c == null || c.ContactId == null) {
            return;
        }

        Task t = new Task(
            WhatId       = c.Id,
            WhoId        = c.ContactId,
            Subject      = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status       = 'Not Started'
        );

        insert t;
    }
}
